# ---------------- Mimari şema (PNG, base64) ----------------
$semaB64 = ''

# ---------------- Word sabitleri ----------------
$wdStyleNormal = -1; $wdStyleHeading1 = -2; $wdStyleHeading2 = -3; $wdStyleHeading3 = -4; $wdStyleTitle = -63
$wdStory = 6; $wdAlignCenter = 1; $wdFormatDocx = 16
$wdBulletGallery = 1; $wdNumberGallery = 2; $wdListApplyToWholeList = 0

$semaYolu = Join-Path ([IO.Path]::GetTempPath()) ("doku_sema_{0}.png" -f [guid]::NewGuid().ToString("N"))
[IO.File]::WriteAllBytes($semaYolu, [Convert]::FromBase64String($semaB64))

$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0
try {
    $doc = $word.Documents.Add()
    $sel = $word.Selection
    $doc.PageSetup.TopMargin = 56; $doc.PageSetup.BottomMargin = 56
    $doc.PageSetup.LeftMargin = 62; $doc.PageSetup.RightMargin = 62
    $sayfaGenisligi = $doc.PageSetup.PageWidth - $doc.PageSetup.LeftMargin - $doc.PageSetup.RightMargin

    function Temizle([string]$s) {
        # Markdown kaçışları (\[ \] \_) ve kod işaretleri
        return ($s -replace '\\([\[\]_*])', '$1')
    }

    # **kalın** ve *italik* parçalarını biçimiyle yazar (paragraf sonu eklemez)
    function Yaz([string]$metin) {
        $metin = Temizle $metin
        $parcalar = [regex]::Split($metin, '(\*\*[^*]+\*\*|\*[^*\s][^*]*\*)')
        foreach ($p in $parcalar) {
            if ($p -eq '') { continue }
            if ($p.StartsWith('**') -and $p.EndsWith('**') -and $p.Length -gt 4) {
                $sel.Font.Bold = $true; $sel.TypeText($p.Substring(2, $p.Length - 4)); $sel.Font.Bold = $false
            } elseif ($p.StartsWith('*') -and $p.EndsWith('*') -and $p.Length -gt 2) {
                $sel.Font.Italic = $true; $sel.TypeText($p.Substring(1, $p.Length - 2)); $sel.Font.Italic = $false
            } else {
                $sel.TypeText($p)
            }
        }
    }

    function Stil([int]$id) { $sel.Style = $doc.Styles.Item($id) }

    function Paragraf([string]$metin, [int]$stil = -1) {
        Stil $stil
        Yaz $metin
        $sel.TypeParagraph()
    }

    # Bir liste (madde ya da numaralı): her liste kendi numarasından (1) başlar
    function Liste([string[]]$maddeler, [bool]$numarali) {
        Stil $wdStyleNormal
        $bas = $sel.Range.Start
        foreach ($m in $maddeler) { Yaz $m; $sel.TypeParagraph() }
        $rng = $doc.Range($bas, $sel.Range.Start - 1)
        $galeri = if ($numarali) { $wdNumberGallery } else { $wdBulletGallery }
        $sablon = $word.ListGalleries.Item($galeri).ListTemplates.Item(1)
        $rng.ListFormat.ApplyListTemplate($sablon, $false, $wdListApplyToWholeList)
        $rng.ParagraphFormat.SpaceAfter = 4
        $sel.EndKey($wdStory) | Out-Null
        $sel.Range.ListFormat.RemoveNumbers()
    }

    function Tablo([string[]]$satirlar) {
        $hucreler = @()
        foreach ($s in $satirlar) {
            if ($s -match '^\|\s*-{3}') { continue }   # ayraç satırı
            $h = $s.Trim().Trim('|').Split('|') | ForEach-Object { Temizle $_.Trim() }
            $hucreler += ,@($h)
        }
        $r = $hucreler.Count; $c = $hucreler[0].Count
        Stil $wdStyleNormal
        $tbl = $doc.Tables.Add($sel.Range, $r, $c)
        $tbl.Borders.Enable = $true
        $tbl.Range.Font.Size = 9.5
        $tbl.Range.ParagraphFormat.SpaceAfter = 0
        for ($i = 0; $i -lt $r; $i++) {
            for ($j = 0; $j -lt $c; $j++) {
                $deger = if ($j -lt $hucreler[$i].Count) { $hucreler[$i][$j] } else { "" }
                $tbl.Cell($i + 1, $j + 1).Range.Text = $deger
            }
        }
        $tbl.Rows.Item(1).Range.Font.Bold = $true
        $tbl.Rows.Item(1).Shading.BackgroundPatternColor = 15132390   # açık gri
        $tbl.Rows.Item(1).HeadingFormat = $true
        $tbl.AutoFitBehavior(1)   # içeriğe göre
        $tbl.AutoFitBehavior(2)   # pencereye sığdır
        $sel.EndKey($wdStory) | Out-Null
        $sel.TypeParagraph()
    }

    function Resim([string]$yol, [string]$altYazi) {
        Stil $wdStyleNormal
        $sel.ParagraphFormat.Alignment = $wdAlignCenter
        $shp = $sel.InlineShapes.AddPicture($yol, $false, $true)
        $shp.LockAspectRatio = -1
        if ($shp.Width -gt $sayfaGenisligi) { $shp.Width = $sayfaGenisligi }
        $sel.TypeParagraph()
        if ($altYazi) {
            $sel.Font.Italic = $true; $sel.Font.Size = 9
            $sel.TypeText($altYazi)
            $sel.Font.Italic = $false; $sel.Font.Size = 11
            $sel.TypeParagraph()
        }
        $sel.ParagraphFormat.Alignment = 0
    }

    # ---------------- Markdown → Word ----------------
    $satirlar = $md -split "`r?`n"
    $i = 0
    $baslikYazildi = $false
    while ($i -lt $satirlar.Count) {
        $s = $satirlar[$i]
        if ($s.Trim() -eq '') { $i++; continue }

        if ($s -match '^# (.+)$') {
            Paragraf $Matches[1] $wdStyleTitle
            $tarih = (Get-Date).ToString("d MMMM yyyy", [Globalization.CultureInfo]::GetCultureInfo("tr-TR"))
            $alt = if ($Hazirlayan) { "$tarih · Hazırlayan: $Hazirlayan" } else { $tarih }
            Stil $wdStyleNormal; $sel.Font.Italic = $true; $sel.TypeText($alt); $sel.Font.Italic = $false; $sel.TypeParagraph()
            $baslikYazildi = $true; $i++; continue
        }
        if ($s -match '^### (.+)$') { Paragraf $Matches[1] $wdStyleHeading3; $i++; continue }
        if ($s -match '^## (.+)$')  { Paragraf $Matches[1] $wdStyleHeading2; $i++; continue }
        if ($s.Trim() -eq '[[SEMA]]') {
            # şemanın altındaki italik satır resim altı yazısı olur
            $alt = ""
            if ($i + 2 -lt $satirlar.Count -and $satirlar[$i + 2] -match '^\*(.+)\*$') { $alt = $Matches[1]; $i += 2 }
            Resim $semaYolu $alt
            $i++; continue
        }
        if ($s -match '^\|') {
            $blok = @()
            while ($i -lt $satirlar.Count -and $satirlar[$i] -match '^\|') { $blok += $satirlar[$i]; $i++ }
            Tablo $blok; continue
        }
        if ($s -match '^- \[ \] ') {
            Stil $wdStyleNormal
            while ($i -lt $satirlar.Count -and $satirlar[$i] -match '^- \[ \] (.+)$') {
                $sel.TypeText([string][char]0x2610 + "  "); Yaz $Matches[1]; $sel.TypeParagraph(); $i++
            }
            continue
        }
        if ($s -match '^\d+\. ') {
            $m = @()
            while ($i -lt $satirlar.Count -and $satirlar[$i] -match '^\d+\. (.+)$') { $m += $Matches[1]; $i++ }
            Liste $m $true; continue
        }
        if ($s -match '^- ') {
            $m = @()
            while ($i -lt $satirlar.Count -and $satirlar[$i] -match '^- (.+)$') { $m += $Matches[1]; $i++ }
            Liste $m $false; continue
        }
        Paragraf $s
        $i++
    }

    # ---------------- Ekler: ekran görüntüleri ----------------
    if ($Ekranlar -and (Test-Path $Ekranlar)) {
        $resimler = Get-ChildItem -Path $Ekranlar -File | Where-Object { $_.Extension -match '^\.(png|jpe?g|bmp|gif)$' } | Sort-Object Name
        if ($resimler) {
            $sel.InsertBreak(7)   # sayfa sonu
            Paragraf "Ekler: Ekran Görüntüleri" $wdStyleHeading2
            foreach ($r in $resimler) { Resim $r.FullName ([IO.Path]::GetFileNameWithoutExtension($r.Name)) }
        }
    }

    $Cikti = [IO.Path]::GetFullPath($Cikti)
    try { $doc.SaveAs2($Cikti, $wdFormatDocx) } catch { $doc.SaveAs([ref]$Cikti, [ref]$wdFormatDocx) }
    $doc.Close()
    Write-Host "Word dosyası oluşturuldu: $Cikti" -ForegroundColor Green
}
finally {
    $word.Quit()
    [void][Runtime.InteropServices.Marshal]::ReleaseComObject($word)
    Remove-Item $semaYolu -ErrorAction SilentlyContinue
}
